// DELAY AGENT: schedule lateness + weather (Open-Meteo) + supplier reliability
const ships = $('Load Shipments').all().map(i => i.json);
const weather = $input.all().map(i => i.json);

const scored = ships.map((s, i) => {
  const w = weather[i] && weather[i].daily ? weather[i].daily : null;
  const rain = w ? Math.max(...w.precipitation_sum.map(Number)) : 0;
  const wind = w ? Math.max(...w.wind_speed_10m_max.map(Number)) : 0;
  let score = 0; const reasons = [];

  const late = s.days_in_transit - s.sched_days;
  if (late > 0) { score += Math.min(40, 20 + late * 8); reasons.push(`already ${late}d behind schedule`); }
  if (rain >= 20) { score += 25; reasons.push(`heavy rain forecast (${rain}mm)`); }
  else if (rain >= 10) { score += 12; reasons.push(`rain forecast (${rain}mm)`); }
  if (wind >= 50) { score += 15; reasons.push(`strong winds (${wind}km/h)`); }
  if (s.supplier_on_time < 0.8) { score += 15; reasons.push(`weak supplier on-time rate (${Math.round(s.supplier_on_time*100)}%)`); }
  if (s.shipping_mode === 'Standard Class') score += 5;

  score = Math.min(100, score);
  const level = score >= 60 ? 'HIGH' : score >= 35 ? 'MEDIUM' : 'LOW';
  return { order_id: s.order_id, city: s.city, supplier: s.supplier, score, level, reasons };
});

const risky = scored.filter(x => x.level !== 'LOW').sort((a, b) => b.score - a.score);
return [{ json: {
  agent: 'delay',
  total_shipments: scored.length,
  high: scored.filter(x => x.level === 'HIGH').length,
  medium: scored.filter(x => x.level === 'MEDIUM').length,
  avg_score: Math.round(scored.reduce((a, b) => a + b.score, 0) / scored.length),
  top_risks: risky.slice(0, 5)
}}];

// COST AGENT: freight cost vs order value, negative-margin orders
const ships = $input.all().map(i => i.json);
const flagged = [];
let totalFreight = 0, totalProfit = 0, totalValue = 0;

for (const s of ships) {
  totalFreight += s.freight_cost; totalProfit += s.profit; totalValue += s.order_value;
  const pct = s.freight_cost / s.order_value;
  const reasons = [];
  if (pct > 0.15) reasons.push(`freight is ${Math.round(pct*100)}% of order value`);
  if (s.profit < 0) reasons.push(`negative profit (${s.profit})`);
  if (reasons.length) flagged.push({ order_id: s.order_id, city: s.city, mode: s.shipping_mode, freight_pct: Math.round(pct*100), profit: s.profit, reasons });
}
return [{ json: {
  agent: 'cost',
  total_freight: totalFreight,
  total_profit: totalProfit,
  avg_freight_pct: Math.round(totalFreight / totalValue * 100),
  flagged_count: flagged.length,
  flagged: flagged.slice(0, 5)
}}];

// INVENTORY AGENT: days of cover vs supplier lead time
const ships = $input.all().map(i => i.json);
const atRisk = [];

for (const s of ships) {
  const cover = +(s.stock / s.daily_demand).toFixed(1);
  if (cover < s.lead_time_days) {
    const reorder = Math.ceil((s.lead_time_days + 7) * s.daily_demand - s.stock);
    atRisk.push({ sku: s.sku, order_id: s.order_id, stock: s.stock, days_of_cover: cover, lead_time_days: s.lead_time_days, suggested_reorder_qty: reorder });
  }
}
atRisk.sort((a, b) => (a.days_of_cover - a.lead_time_days) - (b.days_of_cover - b.lead_time_days));
return [{ json: { agent: 'inventory', stockout_risk_count: atRisk.length, at_risk: atRisk.slice(0, 5) } }];

// Merge ke teeno agent reports ko Groq (OpenAI-compatible) prompt me badalna
const reports = $input.all().map(i => i.json);
const byAgent = {};
reports.forEach(r => byAgent[r.agent] = r);

const system = `You are the Orchestrator of an AI Supply Chain Control Tower.
You receive reports from a Delay Agent, a Cost Agent and an Inventory Agent.
Resolve conflicts between them (e.g. air freight fixes delay but hurts cost) and recommend concrete actions.
Reply with ONLY a valid JSON object (no markdown, no preamble) in this schema:
{"overall_risk":"LOW|MEDIUM|HIGH","summary":"2 sentences",
"recommendations":[{"action":"...","reason":"...","priority":"P1|P2|P3","cost_impact":"e.g. +$400 or -$200","affected":["ORD-xxxx or SKU-xx"]}]}
Give 3 to 5 recommendations, most urgent first.`;

return [{ json: { requestBody: {
  model: $('CONFIG (yahan values paste karo)').first().json.groq_model,
  temperature: 0.2,
  max_tokens: 1500,
  response_format: { type: 'json_object' },
  messages: [
    { role: 'system', content: system },
    { role: 'user', content: 'Agent reports (JSON):\n' + JSON.stringify(byAgent, null, 2) }
  ]
}}}];

// Groq ka JSON parse karke Discord (markdown) approval message banana
const text = ($json.choices && $json.choices[0] && $json.choices[0].message && $json.choices[0].message.content) || '';
let rec;
try { rec = JSON.parse(text.replace(/```json|```/g, '').trim()); }
catch (e) { rec = { overall_risk: 'UNKNOWN', summary: text.slice(0, 500), recommendations: [] }; }

const lines = (rec.recommendations || []).map((r, i) =>
  `**${i + 1}. [${r.priority}] ${r.action}**\n• Why: ${r.reason}\n• Cost impact: ${r.cost_impact}\n• Affected: ${(r.affected || []).join(', ')}`
);
let message = `🚨 **Supply Chain Control Tower**\n**Overall risk: ${rec.overall_risk}**\n${rec.summary}\n\n` + lines.join('\n\n');
if (message.length > 1900) message = message.slice(0, 1900) + '\n…(trimmed)';  // Discord limit 2000 chars
return [{ json: { ...rec, approval_message: message } }];
